/**
 * Post-boot health verification for PROVISION.
 *
 * WHY: two real customer-facing incidents shipped because PROVISION reported
 * DONE on "no API call threw", never "the customer can actually reach what got
 * built" — a VM whose IP collided with unrelated infrastructure (network-layer,
 * nothing ever reachable) and, separately, EVERY game family's `docker run -d`
 * setup script creates no systemd unit, so a game can fail to start while the
 * container still shows "Up" (confirmed: Terraria hung on an interactive
 * world-selection prompt with no TTY, port never bound). Both would have been
 * caught by one real end-to-end check: actually try to reach the server the
 * way a customer would, before ever calling it ready.
 *
 * This module holds the pure retry/resolution logic (unit-testable, see
 * test/provision-health.test.ts) plus the real TCP I/O. worker/index.ts's
 * `provision()` calls `checkSshReachable` / `checkGamePortOpen` and — matching
 * this codebase's established failed-PROVISION convention — simply THROWS on
 * failure; the existing `runJob` catch path takes it from there (retry while
 * attempts remain, else ERROR + release the dedicated IP + notify the
 * customer). This module never touches Server/Job rows itself.
 */
import net from "node:net";
import dgram from "node:dgram";
import { GAME_PORT, type GameFamily } from "../lib/games";

// ---------------------------------------------------------------------------
// Pure retry math — no I/O, safe to unit test directly.
// ---------------------------------------------------------------------------

/**
 * How many attempts a retry window of `timeoutMs` at `intervalMs` cadence
 * allows, counting the first (immediate) attempt. Always at least 1, so a
 * misconfigured zero/negative timeout still tries once rather than looping
 * forever or never trying at all.
 */
export function attemptsFor(timeoutMs: number, intervalMs: number): number {
  if (!Number.isFinite(timeoutMs) || !Number.isFinite(intervalMs) || intervalMs <= 0) return 1;
  return Math.max(1, Math.floor(timeoutMs / intervalMs) + 1);
}

export type CheckOnce = () => Promise<{ ok: true; detail?: string } | { ok: false; error: string }>;

export type RetryResult =
  | { ok: true; detail?: string; attempts: number; elapsedMs: number }
  | { ok: false; error: string; attempts: number; elapsedMs: number };

/**
 * Generic bounded retry: call `checkOnce` up to `attemptsFor(timeoutMs,
 * intervalMs)` times, sleeping `intervalMs` between attempts, stopping early
 * on the first success. `sleep` is injectable so tests can run this at real
 * speed with zero wall-clock delay instead of mocking timers.
 */
export async function retryCheck(
  checkOnce: CheckOnce,
  opts: { timeoutMs: number; intervalMs: number; sleep?: (ms: number) => Promise<void>; now?: () => number }
): Promise<RetryResult> {
  const sleep = opts.sleep ?? ((ms: number) => new Promise((resolve) => setTimeout(resolve, ms)));
  const now = opts.now ?? (() => Date.now());
  const attempts = attemptsFor(opts.timeoutMs, opts.intervalMs);
  const start = now();
  let lastError = "no attempt was made";
  for (let i = 0; i < attempts; i++) {
    const res = await checkOnce();
    if (res.ok) return { ok: true, detail: res.detail, attempts: i + 1, elapsedMs: now() - start };
    lastError = res.error;
    if (i < attempts - 1) await sleep(opts.intervalMs);
  }
  return { ok: false, error: lastError, attempts, elapsedMs: now() - start };
}

// ---------------------------------------------------------------------------
// Game-family / port resolution — pure, no I/O.
// ---------------------------------------------------------------------------

export type ServerFamilyLike = {
  gamePlan?: { gameFamily?: string | null } | null;
  osTemplate?: { family?: string | null } | null;
};

/**

/**
 * Resolve the game family for a server, same precedence as
 * lib/game-config.ts's `familyFor` (game plan first, OS template as
 * fallback) — but WITHOUT requiring a customization schema to exist, since
 * Terraria (this check's motivating incident) has no config schema yet is
 * still a game whose port must be verified. Returns null for a plain VPS or
 * an unrecognized family (never throws — an unknown family is a data/config
 * gap for the caller to log, not a health failure).
 */
export function gameFamilyForServer(server: ServerFamilyLike | null | undefined): GameFamily | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  return fam && Object.prototype.hasOwnProperty.call(GAME_PORT, fam) ? (fam as GameFamily) : null;
}

/** The expected game port + transport for a server, or null (not a recognized game). */
export function gamePortForServer(server: ServerFamilyLike | null | undefined): { port: number; protocol: "tcp" | "udp" } | null {
  const fam = gameFamilyForServer(server);
  return fam ? GAME_PORT[fam] : null;
}

// ---------------------------------------------------------------------------
// Real network I/O — single-attempt probes.
// ---------------------------------------------------------------------------

/** Default per-attempt socket timeout — how long ONE connect (not the whole
 *  retry window) is allowed before giving up and trying again. */
export const TCP_ATTEMPT_TIMEOUT_MS = 5_000;

/**
 * One TCP connect attempt, optionally requiring an SSH banner
 * ("SSH-2.0-...") rather than just a completed handshake — a closed port
 * that drops the connection can otherwise look indistinguishable from a real
 * refusal on some networks, so getting the actual banner is the proof.
 */
function tcpAttempt(
  host: string,
  port: number,
  opts: { timeoutMs: number; expectSshBanner: boolean }
): Promise<{ ok: true; detail?: string } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let settled = false;
    let buf = "";
    const finish = (result: { ok: true; detail?: string } | { ok: false; error: string }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners();
      socket.destroy();
      resolve(result);
    };
    const timer = setTimeout(() => finish({ ok: false, error: "timed out" }), opts.timeoutMs);
    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.once("connect", () => {
      if (!opts.expectSshBanner) finish({ ok: true });
      // else: wait for the banner line on "data" below.
    });
    if (opts.expectSshBanner) {
      socket.on("data", (chunk) => {
        buf += chunk.toString("utf8");
        if (buf.includes("\n") || buf.length >= 256) {
          const line = buf.trim();
          if (line.startsWith("SSH-")) finish({ ok: true, detail: line.slice(0, 120) });
          else finish({ ok: false, error: `connected but no SSH banner (got: ${line.slice(0, 80) || "<empty>"})` });
        }
      });
    }
    socket.connect(port, host);
  });
}

/**
 * One UDP reachability probe. UDP has no handshake, so this cannot PROVE a
 * listener exists the way a TCP connect can — but on Linux, a datagram sent
 * to a UDP port nothing is bound to draws a prompt ICMP port-unreachable,
 * which node surfaces as an `ECONNREFUSED` error on a *connected* UDP socket.
 * No error within the window is treated as reachable. This is the same class
 * of "did the process actually bind the port" evidence the TCP check gives —
 * it would have caught the Terraria-style bug (container up, nothing bound)
 * on a UDP-only game exactly the same way.
 */
function udpAttempt(host: string, port: number, opts: { timeoutMs: number }): Promise<{ ok: true } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const socket = dgram.createSocket("udp4");
    let settled = false;
    const finish = (result: { ok: true } | { ok: false; error: string }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners();
      socket.close();
      resolve(result);
    };
    const timer = setTimeout(() => finish({ ok: true }), opts.timeoutMs);
    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.connect(port, host, () => {
      socket.send(Buffer.from([0]), (err) => {
        if (err) finish({ ok: false, error: (err as NodeJS.ErrnoException).code ?? err.message });
      });
    });
  });
}

// ---------------------------------------------------------------------------
// Public checks used by worker/index.ts's provision().
// ---------------------------------------------------------------------------

/**
 * Retries every ~5s for up to 2 minutes. SSH normally comes up within
 * seconds of the guest booting — cloud-init's user/ssh-key modules run near
 * the START of boot, well before the game/app install `runcmd` — and by the
 * time provision() reaches this check it has usually already waited up to
 * 180s for the guest agent, so sshd has almost always had time. Two minutes
 * of its own headroom on top covers the case where the agent never answers
 * (not every image ships qemu-guest-agent) but sshd is merely slow.
 */
export const SSH_CHECK_TIMEOUT_MS = 120_000;
export const SSH_CHECK_INTERVAL_MS = 5_000;

/**
 * Real TCP connect + SSH banner check against the server's actual reachable
 * address (caller passes the dedicated IP, or the NAT host + assigned SSH
 * port — see worker/index.ts's `dedicated`/`sshPort` computation, reused
 * here rather than recomputed).
 */
export async function checkSshReachable(
  host: string,
  port: number,
  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
): Promise<RetryResult> {
  return retryCheck(() => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: true }), {
    timeoutMs: opts?.timeoutMs ?? SSH_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? SSH_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
  });
}

