import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";
import { GAME_CONFIG_SCHEMAS, schemaFor, validateConfig } from "../lib/game-config.ts";

test("GAME_FAMILIES is a non-empty array of lowercase family slugs", () => {
  assert.ok(Array.isArray(GAME_FAMILIES));
  assert.ok(GAME_FAMILIES.length > 0);
  for (const fam of GAME_FAMILIES) {
    assert.equal(typeof fam, "string");
    assert.match(fam, /^[a-z0-9]+$/);
  }
});

test("GAME_FAMILIES contains the expected known families", () => {
  for (const expected of ["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]) {
    assert.ok(GAME_FAMILIES.includes(expected as (typeof GAME_FAMILIES)[number]), `missing ${expected}`);
  }
});

test("GAME_FAMILIES has no duplicate entries", () => {
  assert.equal(new Set(GAME_FAMILIES).size, GAME_FAMILIES.length);
});

/* ------------------------------------------------------------------ *
 * Game settings: `string` was the only field type with no allowlist
 *
 *   `validateConfig` constrains `enum` to its option list, `int` to its bounds
 *   and `bool` to a boolean — but `string` accepted any 256 characters,
 *   INCLUDING newlines. Those values are written verbatim into LINE-ORIENTED
 *   config files on the customer's live VM by worker/game-config.ts:
 *
 *     updateKeyValue()  ->  server.properties     `motd=<value>`
 *     updateConvars()   ->  Rust server.cfg       `server.hostname "<value>"`
 *     applyValheim()    ->  launch-args file      `-world "<value>"`
 *
 *   A newline therefore does not set one option, it appends further ones. A motd
 *   of "hi\nenable-rcon=true\nrcon.password=x" turns RCON on with a chosen
 *   password — and worker/game-config.ts then reads rcon.port back out of that
 *   same file and interpolates it into an `mcrcon` command line UNQUOTED

test("defaults are shell-inert, so an untouched config can never carry an injection", () => {
  for (const family of Object.keys(GAME_CONFIG_SCHEMAS)) {
    // A `required` field (e.g. DST's TOKEN — no sane platform default exists,
    // see lib/game-config.ts) deliberately has NO safe default and is expected
    // to reject a blank/untouched config; supply a harmless placeholder for
    // those specific fields so this test can still assert every OTHER field's
    // real default is shell-inert.
    const input: Record<string, string> = {};
    for (const f of GAME_CONFIG_SCHEMAS[family].fields) {
      if (f.required) input[f.key] = "test-placeholder";
    }
    const r = validateConfig(family, input);
    assert.equal(r.ok, true, family);
    for (const [k, v] of Object.entries(r.ok ? r.values : {})) {
      if (typeof v !== "string") continue;
      // eslint-disable-next-line no-control-regex
      assert.ok(!/[\x00-\x1f\x7f]/.test(v), `${family}.${k} default contains a control character`);
    }
  }
});

