test("a required field (DST's Klei cluster TOKEN) rejects a blank/untouched value", () => {
  assert.equal(validateConfig("dst", {}).ok, false);
  assert.equal(validateConfig("dst", { TOKEN: "" }).ok, false);
  assert.equal(validateConfig("dst", { TOKEN: "   " }).ok, false, "whitespace-only must not count as provided");
  const r = validateConfig("dst", { TOKEN: "a-real-klei-token" });
  assert.equal(r.ok, true);
